import sys, unittest, shutil
from unittest import mock
from tests._fixtures import VaultFixture

# Simulate Windows: rmtree refuses while the vault's lock handle is open.
real_rmtree = shutil.rmtree

def windows_like_rmtree(path, *a, **k):
    # Find any vault with an open handle under path and deny, like Windows.
    import gc
    from keyvault_ledger import Vault
    for obj in gc.get_objects():
        if isinstance(obj, Vault) and getattr(obj, "_lock_fh", None) is not None:
            try:
                if str(obj._root) in str(path) or str(path) in str(obj._root) or str(path) == str(obj._root) or str(obj._root).startswith(str(path)):
                    raise PermissionError(13, "simulated Windows: file in use (vault.lock)")
            except (ValueError, OSError):
                pass
    return real_rmtree(path, *a, **k)

fixture = VaultFixture(unittest.TestCase())
vault = fixture.open()
vault.seal("k", b"m")
with mock.patch.object(shutil, "rmtree", side_effect=windows_like_rmtree):
    with mock.patch.object(vault, "close", side_effect=RuntimeError("simulated close failure")):
        try:
            fixture._cleanup()
            print("RESULT: no exception")
        except BaseException as exc:
            print("RESULT:", type(exc).__name__, "->", str(exc)[:120])
            print("cause:", type(exc.__cause__).__name__ if exc.__cause__ else None)
# cleanup leftover for real
try:
    vault.close()
except Exception:
    pass
real_rmtree(fixture.tmp_path, ignore_errors=True)
